INSERT INTO AYA100 (
					MNLA_NO
					,MNLA_CN
					,USE_YN
					,FRST_RGTR_ID
					,FRST_REG_DT
					,LAST_MDFR_ID
					,LAST_MDFCN_DT
					)
VALUES((
		SELECT MAX(MNLA_NO)+1 
		FROM AYA100
		)
		, #{MNLA_CN}
		, 'N'
		, #{FRST_RGTR_ID}
		, SYSDATE
		, #{LAST_MDFR_ID}
		, SYSDATE
       )
